<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue'
import {useRouter} from 'vue-router'
import {ElMessage} from 'element-plus/es/components/message/index'
import {ElMessageBox} from 'element-plus/es/components/message-box/index'
import {Plus,Search,Refresh} from '@element-plus/icons-vue'
import {api,report} from '../api'
import {useAuth} from '../stores/auth'
import type {Customer} from '../types'
const auth=useAuth(),router=useRouter(),rows=ref<Customer[]>([]),total=ref(0),loading=ref(false),busy=ref(false),open=ref(false),detail=ref<Customer|null>(null),conflict=ref(false)
const query=reactive({q:'',status:'',page:1,size:10})
const empty=()=>({id:0,name:'',contact:'',email:'',industry:'软件服务',status:'active',version:1})
const form=reactive(empty())
async function load(){loading.value=true;try{const {data}=await api.get('/customers',{params:query});rows.value=data.items;total.value=data.total}catch(e){report(e)}finally{loading.value=false}}
function search(){query.page=1;load()}
function edit(row?:Customer){Object.assign(form,row??empty());conflict.value=false;open.value=true}
async function save(){if(!form.name.trim()||!form.contact.trim()||!form.industry.trim()){ElMessage.warning('请填写客户名称、联系人和行业');return}busy.value=true;try{await (form.id?api.put('/customers/'+form.id,form):api.post('/customers',form));open.value=false;ElMessage.success('客户档案已保存');await load()}catch(e){conflict.value=report(e)===409}finally{busy.value=false}}
async function reloadForm(){try{await ElMessageBox.confirm('载入后将替换当前未保存内容，请先复制需要保留的信息。','载入最新档案',{confirmButtonText:'载入',cancelButtonText:'继续编辑'});Object.assign(form,(await api.get('/customers/'+form.id)).data);conflict.value=false}catch(e){if(e!=='cancel'&&e!=='close')report(e)}}
async function inspect(row:Customer){try{detail.value=(await api.get('/customers/'+row.id)).data}catch(e){report(e)}}
onMounted(load)
</script>
<template><div class="page-heading"><div><h1>客户档案</h1><p>统一维护客户信息，关联合同业务记录。</p></div><el-button v-if="auth.writable" type="primary" :icon="Plus" @click="edit()">新增客户</el-button></div><section class="panel"><div class="filters"><el-input v-model="query.q" placeholder="客户名称 / 联系人" clearable @keyup.enter="search"/><el-select v-model="query.status" placeholder="全部状态" clearable><el-option label="启用中" value="active"/><el-option label="已停用" value="inactive"/></el-select><el-button type="primary" :icon="Search" @click="search">查询</el-button><el-button :icon="Refresh" @click="Object.assign(query,{q:'',status:'',page:1});load()">重置</el-button></div><el-table v-loading="loading" :data="rows" empty-text="暂无匹配的客户"><el-table-column label="客户名称" min-width="220"><template #default="{row}"><button class="link" @click="inspect(row)">{{row.name}}</button><div class="cell-sub">客户编号 CU-{{row.id}}</div></template></el-table-column><el-table-column prop="contact" label="联系人" min-width="110"/><el-table-column prop="industry" label="行业" min-width="110"/><el-table-column prop="email" label="联系邮箱" min-width="200"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='active'?'success':'info'" effect="light">{{row.status==='active'?'启用中':'已停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="130"><template #default="{row}"><el-button text type="primary" @click="inspect(row)">详情</el-button><el-button v-if="auth.writable" text type="primary" @click="edit(row)">编辑</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="query.page" :page-size="query.size" :total="total" layout="total, prev, pager, next" @current-change="load"/></div></section>
<el-dialog v-model="open" :title="form.id?'编辑客户':'新增客户'" width="580px" :close-on-click-modal="false"><div class="hint">停用客户后，历史合同继续保留；该客户不能再创建或提交新合同。</div><el-alert v-if="conflict" class="error-box" type="warning" :closable="false" title="档案已被其他成员修改。当前输入已保留。"><el-button text type="primary" @click="reloadForm">载入最新档案</el-button></el-alert><el-form :model="form" label-position="top"><div class="form-grid"><el-form-item class="wide" label="客户名称" required><el-input v-model="form.name" maxlength="120"/></el-form-item><el-form-item label="联系人" required><el-input v-model="form.contact" maxlength="120"/></el-form-item><el-form-item label="所属行业" required><el-input v-model="form.industry" maxlength="60"/></el-form-item><el-form-item class="wide" label="联系邮箱"><el-input v-model="form.email" maxlength="160" type="email"/></el-form-item><el-form-item label="客户状态"><el-select v-model="form.status"><el-option label="启用中" value="active"/><el-option label="已停用" value="inactive"/></el-select></el-form-item></div></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="conflict" @click="save">保存客户</el-button></template></el-dialog>
<el-drawer :model-value="!!detail" title="客户详情" :size="'min(560px, 100vw)'" @close="detail=null"><template v-if="detail"><h2 class="detail-title">{{detail.name}}</h2><div v-for="item in [['联系人',detail.contact],['行业',detail.industry],['邮箱',detail.email||'未填写'],['状态',detail.status==='active'?'启用中':'已停用']]" :key="item[0]" class="detail-line"><span>{{item[0]}}</span><span>{{item[1]}}</span></div><h3 class="subheading">关联合同 · {{detail.contracts?.length??0}} 份</h3><p class="muted">查看该客户的全部合同与处理状态。</p><el-button type="primary" plain style="margin-top:20px" @click="router.push({path:'/contracts',query:{customer_id:detail.id}})">查看关联合同</el-button></template></el-drawer></template>
